import { Component, OnInit, OnDestroy  } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, FormArray, Validators, ReactiveFormsModule } from '@angular/forms';

@Component({
  selector: 'app-parcial',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './edicion.component.html',
})
export class EdicionComponent implements OnInit {
  public miFormulario: FormGroup;
  public eventos: any[] = [];
  public servicios: any[] = [];
  private urlAPI: String = 'http://localhost/parcial22024/public/api/?accion=';

  constructor(private http: HttpClient, private fb: FormBuilder)
  {
    this.miFormulario = this.fb.group({
      id: [null, []],
      nombre: ['', [Validators.required ]],
      fecha: ['', [Validators.required, Validators.min(1900) ]],
      servicios: [[], []]
    });
  }



  enviar() {
    if (this.miFormulario.value.id==null) {
      this.http.post(this.urlAPI + 'eventos/', this.miFormulario.value)
        .subscribe(
          (response: any) => {
            this.cargarEventos();
            this.miFormulario.reset();
          },
          (error) => {
            console.error(error);
          }
        );
    } else {
      this.http.patch(this.urlAPI + 'eventos/' + this.miFormulario.value.id, this.miFormulario.value)
        .subscribe(
          (response: any) => {
            this.cargarEventos();
            this.miFormulario.reset();
          },
          (error) => {
            console.error(error);
          }
        );
    }
  }

  editar(id: number) {
    this.http.get(this.urlAPI + 'eventos/' + id)
      .subscribe(
        (response: any) => {
          this.miFormulario.reset(response);
        },
        (error) => {
          console.error(error);
        }
      );
  }

  borrar(id: number) {
    if (confirm('¿Estás seguro de querer borrar este evento?')) {
      this.http.delete(this.urlAPI + 'eventos/'+ id)
        .subscribe(
          (response: any) => {
            console.log('Borrado ok #' + id);
            this.cargarEventos();
          },
          (error) => {
            console.error(error);
          }
        );
    }
  }

  // DE REGALO!
  cargarEventos() {
    this.http.get(this.urlAPI + 'eventos')
      .subscribe(
        (response: any) => {
          this.eventos = response;
         },
        (error) => {
          console.error(error);
        }
      );
  }

  ngOnInit() {
    this.cargarEventos();

    this.http.get(this.urlAPI+ 'servicios')
    .subscribe(
      (response: any) => {
        this.servicios = response;
      },
      (error) => {
        console.error(error);
      }
    );
  }

  restablecerBD (): void
  {
    this.http.post(this.urlAPI + 'restablecer', {})
      .subscribe(
        (response: any) => {
          let ya = new Date();
          console.log("Restablecido Ok " + ya.toISOString());
          this.cargarEventos();
        },
        (error) => {
          console.error(error);
        }
      );
  }








}

